 const rates=doc.settings?.depreciationRates||{},groups=Object.keys(rates).length?Object.keys(rates):['عمومی'],inp=(n,l,val,cls='',ph='')=>P.field(l,`<input class="input ${cls}" name="${n}" value="${esc(val??'')}" placeholder="${ph}">`);
