window.CatalogReal={preparedList,preparedForm,supplierListsForm,supplierExport,supplierImport,ingredientForm,pricesForm,menuForm,supplierForm,supplierItems:supplierItemsForm,supplierArchive,supplierFoot,assetForm,assetAction:()=>can('assets')?`<button class="btn btn-primary" onclick="CatalogReal.assetForm()">${P.ic('plus')}دارایی جدید</button>`:'',can,whyK};
